package com.smarttask.security;
import com.smarttask.repository.UserRepository; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.UsernamePasswordAuthenticationToken; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.security.web.authentication.WebAuthenticationDetailsSource; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.IOException;
@Component public class JwtAuthFilter extends OncePerRequestFilter { private final JwtService jwt; private final UserRepository users; public JwtAuthFilter(JwtService j,UserRepository u){jwt=j;users=u;} @Override protected void doFilterInternal(HttpServletRequest req,HttpServletResponse res,FilterChain chain)throws ServletException,IOException{String h=req.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{String email=jwt.subject(h.substring(7));if(users.findByEmail(email).isPresent()&&SecurityContextHolder.getContext().getAuthentication()==null){var a=new UsernamePasswordAuthenticationToken(email,null,java.util.List.of());a.setDetails(new WebAuthenticationDetailsSource().buildDetails(req));SecurityContextHolder.getContext().setAuthentication(a);}}catch(RuntimeException ignored){}chain.doFilter(req,res);} }
